class Memory { final String id; final String content; final String conversationId; final Map<String, dynamic> metadata; DateTime createdAt; DateTime lastAccess; int accessCount; Memory({required this.id, required this.content, required this.conversationId, this.metadata = const {}, DateTime? createdAt, DateTime? lastAccess, this.accessCount = 0}) : createdAt = createdAt ?? DateTime.now(), lastAccess = lastAccess ?? DateTime.now(); }
class MemoryStats { final int total; final DateTime lastUpdate; const MemoryStats({required this.total, required this.lastUpdate}); factory MemoryStats.empty() => MemoryStats(total: 0, lastUpdate: DateTime.now()); }
